    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.securities = {}
        self.smas = {}
        self.rsis = {}
        self.previous_closes = {}
        self.red_day_counts = {}
        self.daily_data_ready = {}

        # Strategy A (SPY)
        self.spy_symbol = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.smas[self.spy_symbol] = self.SMA(self.spy_symbol, 20, Resolution.Daily) # Example SMA, rule didn't specify period

        # Strategy B (AAPL)
        self.aapl_symbol = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.rsis[self.aapl_symbol] = self.RSI(self.aapl_symbol, 14, Resolution.Daily)

        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.securities[symbol] = self.Securities[symbol]
            self.previous_closes[symbol] = deque(maxlen=2)
            self.red_day_counts[symbol] = 0
            self.daily_data_ready[symbol] = False

        self.SetWarmUp(20) # Max indicator lookback

        # Lot management
        self.lot_A_shares = 0
        self.lot_B_shares = 0

    def OnData(self, data):
        # Wait for all indicators to warm up and all securities to have data
        if self.IsWarmingUp:
            return

        # Check if today's bar is missing for ANY subscribed ticker
        for symbol in self.securities:
            if not data.ContainsKey(symbol) or not data[symbol].Close:
                # If data is missing for any symbol, skip all rule evaluation for this day
                return

        # Update historical data for red day calculation and previous close
        for symbol in self.securities:
            if data.ContainsKey(symbol) and data[symbol].Close:
                self.previous_closes[symbol].append(data[symbol].Close)

                if len(self.previous_closes[symbol]) > 1:
                    today_close = self.previous_closes[symbol][-1]
                    yesterday_close = self.previous_closes[symbol][-2]

                    if today_close < yesterday_close:
                        self.red_day_counts[symbol] += 1
                    else:
                        self.red_day_counts[symbol] = 0

        # Ensure all indicators are ready
        if not all(sma.IsReady for sma in self.smas.values()):
            return
        if not all(rsi.IsReady for rsi in self.rsis.values()):
            return

        # Evaluate Sells before Buys

        # Strategy A Sell
        self.evaluate_strategy_A_sell(data)

        # Strategy B Sell
        self.evaluate_strategy_B_sell(data)

        # Strategy A Buy
        self.evaluate_strategy_A_buy(data)

        # Strategy B Buy
        self.evaluate_strategy_B_buy(data)


