        if self.lot_A_shares > 0:
            spy_close = data[self.spy_symbol].Close
            spy_sma = self.smas[self.spy_symbol].Current.Value

            # SPY's close crosses below its moving average
            if len(self.previous_closes[self.spy_symbol]) > 1:
                yesterday_close = self.previous_closes[self.spy_symbol][-2]
                yesterday_sma = self.smas[self.spy_symbol].History(self.spy_symbol, 1, Resolution.Daily).iloc[0][0] if self.smas[self.spy_symbol].IsReady else None

                if yesterday_close is not None and yesterday_sma is not None:
                    if yesterday_close >= yesterday_sma and spy_close < spy_sma:
                        # Liquidate Strategy A's entire lot
                        self.Liquidate(self.spy_symbol)
                        self.lot_A_shares = 0
                        self.Debug(f"{self.Time} - SPY Strategy A SELL: Close below SMA. Liquidated lot. Shares: {self.lot_A_shares}")

    def evaluate_strategy_A_buy(self, data):
        if self.lot_A_shares == 0:
            spy_close = data[self.spy_symbol].Close
            spy_sma = self.smas[self.spy_symbol].Current.Value

            # SPY's close crosses above its moving average
            if len(self.previous_closes[self.spy_symbol]) > 1:
                yesterday_close = self.previous_closes[self.spy_symbol][-2]
                yesterday_sma = self.smas[self.spy_symbol].History(self.spy_symbol, 1, Resolution.Daily).iloc[0][0] if self.smas[self.spy_symbol].IsReady else None

                if yesterday_close is not None and yesterday_sma is not None:
                    if yesterday_close <= yesterday_sma and spy_close > spy_sma:
                        # Invest 40% of total portfolio value in SPY
                        self.SetHoldings(self.spy_symbol, 0.40)
                        self.lot_A_shares = self.Portfolio[self.spy_symbol].Quantity
                        self.Debug(f"{self.Time} - SPY Strategy A BUY: Close above SMA. Invested 40%. Shares: {self.lot_A_shares}")

    def evaluate_strategy_B_sell(self, data):
        if self.lot_B_shares > 0:
            aapl_rsi = self.rsis[self.aapl_symbol].Current.Value

            # AAPL's 14-day RSI closes above 60
            if aapl_rsi > 60:
                # Liquidate Strategy B's entire lot
                self.Liquidate(self.aapl_symbol)
                self.lot_B_shares = 0
                self.Debug(f"{self.Time} - AAPL Strategy B SELL: RSI above 60. Liquidated lot. Shares: {self.lot_B_shares}")

    def evaluate_strategy_B_buy(self, data):
        if self.lot_B_shares == 0:
            # AAPL has been red for 3 consecutive days
            if self.red_day_counts[self.aapl_symbol] >= 3:
                # Buy $20,000 of AAPL if at least $20,000 cash is available
                investment_amount = 20000
                if self.Portfolio.Cash >= investment_amount:
                    aapl_price = data[self.aapl_symbol].Close
                    if aapl_price > 0:
                        shares_to_buy = int(investment_amount / aapl_price)
                        if shares_to_buy > 0:
                            self.Buy(self.aapl_symbol, shares_to_buy)
                            self.lot_B_shares = self.Portfolio[self.aapl_symbol].Quantity # Update lot shares after order fills
                            self.Debug(f"{self.Time} - AAPL Strategy B BUY: 3 consecutive red days. Bought {shares_to_buy} shares. Shares: {self.lot_B_shares}")
                        else:
                            self.Debug(f"{self.Time} - AAPL Strategy B BUY skipped: Calculated shares to buy was 0 due to price.")
                    else:
                        self.Debug(f"{self.Time} - AAPL Strategy B BUY skipped: AAPL price is zero.")
                else:
                    self.Debug(f"{self.Time} - AAPL Strategy B BUY skipped: Not enough cash ($20k) available. Current cash: {self.Portfolio.Cash}")

