class LeanAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.securities = {}
        for ticker in self.tickers:
            self.securities[ticker] = self.AddEquity(ticker, Resolution.Daily)
            self.securities[ticker].SetFeeModel(self.ConstantFeeModel()) # To handle fractional shares in backtest for clarity, though not strictly required by problem.

        self.data_history = {}
        self.required_history_days = {
            "SPY_SMA": 100,
            "AAPL_RedDays": 3,
            "AAPL_RSI": 14
        }
        self.max_required_history = max(self.required_history_days.values())

        # Strategy A (SPY)
        self.spy_sma = self.SMA("SPY", 100, Resolution.Daily)
        self.spy_lot_held = False
        self.spy_last_close = 0.0

        # Strategy B (AAPL)
        self.aapl_red_days_count = 0
        self.aapl_last_close = 0.0
        self.aapl_rsi = self.RSI("AAPL", 14, Resolution.Daily)
        self.aapl_lot_held = False

        self.is_warmup_complete = False

    def OnData(self, data):
        if not self.is_warmup_complete:
            # Check if all indicators and rolling windows have enough history
            if not (self.spy_sma.IsReady and self.aapl_rsi.IsReady):
                return

            # Check if we have enough historical data for red day calculation
            # We need at least self.max_required_history days of close prices for each security
            # to ensure all rules can be evaluated.

            # For simplicity and robustness, we will check if all securities have at least max_required_history + 1 (for current day close)
            # available in history to compute red days correctly, and all indicators are ready.
            for ticker in self.tickers:
                if not self.securities[ticker].HasData:
                    return # Data not yet available for a security, wait.

            # After indicators are ready and we have initial data, we need to populate self.data_history for prior day comparisons
            for ticker_symbol in self.tickers:
                self.data_history[ticker_symbol] = []

            history_start = self.Time - timedelta(days=self.max_required_history + 50) # Buffer
            history_data = self.History([s.Symbol for s in self.securities.values()], history_start, self.Time, Resolution.Daily).droplevel(0)

            for ticker_symbol in self.tickers:
                ticker_df = history_data.loc[ticker_symbol].close
                for dt, close_price in ticker_df.items():
                    self.data_history[ticker_symbol].append({'time': dt.date(), 'close': float(close_price)})

            # Initialize last close prices
            if "SPY" in data and data["SPY"] is not None:
                self.spy_last_close = data["SPY"].Close
            if "AAPL" in data and data["AAPL"] is not None:
