                self.RegisterIndicator(self.securities[ticker], self.rsi_14[ticker], timedelta(days=1))

        # Strategy A state
        self.strategy_a_shares = 0
        self.strategy_a_bought_price = 0

        # Strategy B state
        self.strategy_b_shares = 0
        self.consecutive_red_days = {}
        for ticker in self.tickers:
            self.consecutive_red_days[ticker] = 0

        self.data_ready = False

    def OnData(self, data):
        # Check for missing data
        for ticker in self.tickers:
            if not data.ContainsKey(self.securities[ticker]) or not data[self.securities[ticker]]:
                return # Skip ALL rule evaluation for that day

        # Update history frames and previous closes
        for ticker in self.tickers:
            if data.ContainsKey(self.securities[ticker]):
                bar = data[self.securities[ticker]]
                self.history_frames[ticker] = pd.concat([self.history_frames[ticker], 
                                                         pd.DataFrame([{'open': bar.Open, 'high': bar.High, 'low': bar.Low, 'close': bar.Close, 'volume': bar.Volume}], 
                                                                      index=[self.Time])]).iloc[-200:] # Keep enough history for indicators

                # Update consecutive red days
                if ticker in self.previous_closes:
                    if bar.Close < self.previous_closes[ticker]:
                        self.consecutive_red_days[ticker] += 1
                    else:
                        self.consecutive_red_days[ticker] = 0
                self.previous_closes[ticker] = bar.Close

        # Wait for indicators to be ready
        if not self.data_ready:
            if self.m_a_100["SPY"].IsReady and self.rsi_14["AAPL"].IsReady:
                self.data_ready = True
            else:
                return

        # ============================================
        # Strategy A (SPY)
        # ============================================
        spy_close = self.Securities["SPY"].Close
        spy_previous_close = self.history_frames["SPY"]['close'].iloc[-2] if len(self.history_frames["SPY"]) >= 2 else None
        spy_ma_100_today = self.m_a_100["SPY"].Current.Value
        spy_ma_100_yesterday = self.m_a_100["SPY"].Previous.Value

        # Sell Logic (Strategy A)
        if self.strategy_a_shares > 0 and spy_previous_close is not None and spy_ma_100_yesterday is not None:
            if spy_previous_close > spy_ma_100_yesterday and spy_close <= spy_ma_100_today: # Crosses below
                self.Liquidate("SPY")
                self.strategy_a_shares = 0
                self.Debug(f"Strategy A: Liquidated SPY on {self.Time}")

        # Buy Logic (Strategy A)
        if self.strategy_a_shares == 0 and spy_previous_close is not None and spy_ma_100_yesterday is not None:
            if spy_previous_close <= spy_ma_100_yesterday and spy_close > spy_ma_100_today: # Crosses above
                # Invest 40% of total portfolio value
                investment_amount = self.Portfolio.TotalPortfolioValue * 0.40
                self.strategy_a_shares = self.CalculateOrderQuantity("SPY", investment_amount / self.Portfolio.TotalPortfolioValue)
                self.Buy("SPY", self.strategy_a_shares)
                self.Debug(f"Strategy A: Bought {self.strategy_a_shares} SPY shares on {self.Time}")

        # ============================================
        # Strategy B (AAPL)
        # ============================================
        aapl_close = self.Securities["AAPL"].Close
        aapl_rsi_today = self.rsi_14["AAPL"].Current.Value

        # Sell Logic (Strategy B)
        if self.strategy_b_shares > 0:
            if aapl_rsi_today > 60:
                self.Liquidate("AAPL")
                self.strategy_b_shares = 0
                self.Debug(f"Strategy B: Liquidated AAPL on {self.Time}")

        # Buy Logic (Strategy B)
        if self.strategy_b_shares == 0:
            if self.consecutive_red_days["AAPL"] >= 3:
                # Buy $20,000 of AAPL if at least $20,000 cash is available
                if self.Portfolio.Cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy("AAPL", shares_to_buy)
                        self.strategy_b_shares = shares_to_buy
                        self.Debug(f"Strategy B: Bought {self.strategy_b_shares} AAPL shares on {self.Time}")
